using System.ComponentModel.DataAnnotations;
using System.Net;
using System.Net.Http.Json;
using System.Text.Json.Nodes;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging.Abstractions;
using Nexora.BuildingBlocks.Security;
using Nexora.Modules.Identity;
using Nexora.Modules.Workflow;
using static Nexora.Api.Tests.WorkflowTestClient;
namespace Nexora.Api.Tests;
public sealed class WorkflowCatalogueTests
{
 private static async Task<WorkflowActionResult> Invoke(IdentityApiFactory app,HttpClient client,string action,Dictionary<string,string> input,Guid? actionId=null)
 {
  var session=(await client.GetFromJsonAsync<SessionResponse>("/api/v1/auth/session"))!;using var identity=app.Services.GetRequiredService<WorkflowExecutionContext>().Enter(new(session.TenantId,session.UserId,session.Permissions.ToArray()));await using var scope=app.Services.CreateAsyncScope();var handler=scope.ServiceProvider.GetServices<IWorkflowActionHandler>().Single(x=>x.Descriptor.Key==action);return await handler.ExecuteDetailedAsync(new(Guid.NewGuid(),"test",actionId??Guid.NewGuid(),session.UserId,"Catalogue check",Guid.Empty),input,default);
 }
 private static async Task<JsonNode> Invoice(HttpClient client,string customer,decimal amount=100)
 {
  var product=await Json(await Send(client,"/api/v1/finance/products",HttpMethod.Post,new{name="Renewal",sku=Guid.NewGuid().ToString(),unitPrice=amount,currency="GBP",vatBasisPoints=0}));var order=await Json(await Send(client,"/api/v1/finance/orders",HttpMethod.Post,new{customerId=customer,lines=new[]{new{productId=Id(product),quantity=1}}}));return await Json(await Send(client,$"/api/v1/finance/orders/{Id(order)}/post",HttpMethod.Post,new{version=Version(order)}));
 }
 [Fact] public async Task Catalogue_saves_all_29_and_variants_idempotently_without_activation_or_overwriting_edits()
 {
  using var app=new IdentityApiFactory();using var client=await Login(app);var result=await Json(await Send(client,"/api/v1/workflows/catalogue/install",HttpMethod.Post,new{}));Assert.Empty(result["skipped"]!.AsArray());Assert.Equal(34,result["installed"]!.AsArray().Count);var catalogue=(await Json(await client.GetAsync("/api/v1/workflows/catalogue"))).AsArray();Assert.Equal(29,catalogue.Count);Assert.All(catalogue,row=>{Assert.True(row!["saved"]!.GetValue<bool>());Assert.False(row["active"]!.GetValue<bool>());});
  var selected=catalogue[0]!["definitionId"]!.GetValue<string>();var detail=await Json(await client.GetAsync("/api/v1/workflows/definitions/"+selected));await Json(await Send(client,"/api/v1/workflows/definitions/"+selected,HttpMethod.Put,new{name="Preserve my edited workflow",description="",graph=JsonNode.Parse(detail["definition"]!["draftJson"]!.GetValue<string>()),version=Version(detail["definition"]!)}));var repeated=await Json(await Send(client,"/api/v1/workflows/catalogue/install",HttpMethod.Post,new{}));Assert.All(repeated["installed"]!.AsArray(),row=>Assert.False(row!["created"]!.GetValue<bool>()));Assert.Equal("Preserve my edited workflow",(await Json(await client.GetAsync("/api/v1/workflows/definitions/"+selected)))["definition"]!["name"]!.GetValue<string>());
 }
 [Fact] public async Task Required_configuration_blocks_publication_until_values_are_supplied()
 {
  using var app=new IdentityApiFactory();using var client=await Login(app);var template=await Json(await Send(client,"/api/v1/workflows/templates/event-registration/draft",HttpMethod.Post,new{}));var draft=await Json(await Send(client,"/api/v1/workflows/definitions",HttpMethod.Post,new{name="Needs registration Contact",graph=template["graph"]}));Assert.Equal(HttpStatusCode.BadRequest,(await Send(client,$"/api/v1/workflows/definitions/{Id(draft)}/publish",HttpMethod.Post,new{version=Version(draft)})).StatusCode);
 }
 [Fact] public async Task Quality_inspection_flags_duplicates_without_merging_or_mutating_records()
 {
  using var app=new IdentityApiFactory();using var client=await Login(app);var first=await Contact(client);await Contact(client);var result=await Invoke(app,client,"crm.record.inspect-quality",new(){{"recordId",Id(first)}});Assert.Equal("1",result.Outputs["duplicateCount"]);Assert.Equal("true",result.Outputs["needsReview"]);Assert.Equal(2,(await Json(await client.GetAsync("/api/v1/crm/records?kind=contact")))["items"]!.AsArray().Count);
 }
 [Fact] public async Task Finance_adjustment_retains_balance_guard_and_idempotent_receipt()
 {
  using var app=new IdentityApiFactory();using var client=await Login(app);var contact=await Contact(client);var invoice=await Invoice(client,Id(contact));var actionId=Guid.NewGuid();var input=new Dictionary<string,string>{{"invoiceId",Id(invoice)},{"amount","10"},{"currency","GBP"},{"reference","credit-reviewed"},{"reason","Approved adjustment"}};await Invoke(app,client,"finance.credit.record",input,actionId);await Invoke(app,client,"finance.credit.record",input,actionId);var detail=await Json(await client.GetAsync($"/api/v1/finance/invoices/{Id(invoice)}"));Assert.Single(detail["credits"]!.AsArray());Assert.Equal(90,detail["balance"]!.GetValue<decimal>());input["amount"]="100";await Assert.ThrowsAsync<ValidationException>(()=>Invoke(app,client,"finance.credit.record",input));
 }
 [Fact] public async Task Content_publication_pins_reviewed_revision_and_rejects_a_changed_draft()
 {
  using var app=new IdentityApiFactory();using var client=await Login(app);await Json(await Send(client,"/api/v1/content/site",HttpMethod.Post,new{name="Catalogue website",tagline=""}));var created=await Json(await Send(client,"/api/v1/content/pages",HttpMethod.Post,new{slug="reviewed",title="Initial",description="",blocks=new[]{new{type="text",heading="",text="Reviewed text"}}}));var page=created["page"]!;var inspect=await Invoke(app,client,"content.page.inspect-draft",new(){{"pageId",Id(page)}});await Json(await Send(client,"/api/v1/content/pages/"+Id(page),HttpMethod.Put,new{slug="reviewed",title="Changed",description="",blocks=new[]{new{type="text",heading="",text="New text needs approval"}},version=Version(page)}));await Assert.ThrowsAsync<ValidationException>(()=>Invoke(app,client,"content.page.publish",new(){{"pageId",Id(page)},{"revisionId",inspect.Outputs["revisionId"]!}}));var current=await Invoke(app,client,"content.page.inspect-draft",new(){{"pageId",Id(page)}});var published=await Invoke(app,client,"content.page.publish",new(){{"pageId",Id(page)},{"revisionId",current.Outputs["revisionId"]!}});Assert.Equal(current.Outputs["revisionId"],published.Outputs["revisionId"]);
 }
 [Theory]
 [InlineData(false, false)]
 [InlineData(true, false)]
 [InlineData(true, true)]
 public async Task Payment_completion_requires_reconciled_linked_settlement_and_cannot_reuse_invoice(bool usePayer, bool invoiceToAccount)
 {
  using var app=new IdentityApiFactory();using var client=await Login(app);var contact=await Contact(client);var product=await Json(await Send(client,"/api/v1/membership/products",HttpMethod.Post,new{name="Paid offering",category="Professional",termMonths=12,rate=100,currency="GBP",isActive=true}));await Json(await Send(client,$"/api/v1/membership/products/{Id(product)}/policy",HttpMethod.Put,new{renewalMode="rolling",yearEndMonth=12,yearEndDay=31,processingFee=0,credit=0,requirePayment=true}));var application=await Json(await Send(client,"/api/v1/membership/applications",HttpMethod.Post,new{contactId=Id(contact),productId=Id(product),startsAtUtc=DateTime.UtcNow.Date,applicationType="individual",termsAccepted=true}));var approved=await Json(await Send(client,$"/api/v1/membership/applications/{Id(application)}/decision",HttpMethod.Post,new{version=Version(application),decision="approve",reason="Reviewed"}));var memberId=approved["membershipId"]!.GetValue<string>();var member=(await Json(await client.GetAsync("/api/v1/membership/members/"+memberId)))["member"]!;var customerId=Id(contact);
  if(usePayer){var payer=await Json(await Send(client,"/api/v1/crm/records",HttpMethod.Post,new{kind="account",name="Membership payer",status="active"}),HttpStatusCode.Created);var recipient=await Json(await Send(client,"/api/v1/crm/records",HttpMethod.Post,new{kind="account",name="Invoice account",status="active"}),HttpStatusCode.Created);await Json(await Send(client,"/api/v1/membership/members/"+memberId+"/financial-arrangement",HttpMethod.Put,new{version=Version(member),details=new{paidById=Id(payer),invoiceToAccount,invoicingAccountId=invoiceToAccount?Id(recipient):null},reason="Authorised billing arrangement"}));customerId=invoiceToAccount?Id(recipient):Id(payer);var wrongInvoice=await Invoice(client,Id(contact));await Assert.ThrowsAsync<ValidationException>(()=>Invoke(app,client,"membership.member.renew-settled",new(){{"membershipId",memberId},{"invoiceId",Id(wrongInvoice)},{"termEndUtc",member["endsAtUtc"]!.GetValue<string>()},{"reason","Wrong billing customer"}}));}
  var invoice=await Invoice(client,customerId);var receipt=await Json(await Send(client,"/api/v1/finance/receipts",HttpMethod.Post,new{customerId,reference="Bank receipt",amount=100,currency="GBP"}));await Json(await Send(client,"/api/v1/finance/allocations",HttpMethod.Post,new{invoiceId=Id(invoice),receiptId=Id(receipt),amount=100}));var input=new Dictionary<string,string>{{"membershipId",memberId},{"invoiceId",Id(invoice)},{"termEndUtc",member["endsAtUtc"]!.GetValue<string>()},{"reason","Linked obligation verified"}};await Assert.ThrowsAsync<ValidationException>(()=>Invoke(app,client,"membership.member.renew-settled",input));await Json(await Send(client,$"/api/v1/finance/receipts/{Id(receipt)}/reconcile",HttpMethod.Post,new{version=Version((await Json(await client.GetAsync($"/api/v1/finance/receipts/{Id(receipt)}")))["receipt"]!),statementReference="Verified bank statement",amount=100,currency="GBP"}));var effect=Guid.NewGuid();var renewed=await Invoke(app,client,"membership.member.renew-settled",input,effect);var replay=await Invoke(app,client,"membership.member.renew-settled",input,effect);Assert.Equal(renewed.Outputs["endsAtUtc"],replay.Outputs["endsAtUtc"]);input["termEndUtc"]=renewed.Outputs["endsAtUtc"]!;await Assert.ThrowsAsync<ValidationException>(()=>Invoke(app,client,"membership.member.renew-settled",input));
 }
 [Fact] public async Task Community_leave_uses_domain_command_and_replays_without_another_delete()
 {
  using var app=new IdentityApiFactory();using var client=await Login(app);var contact=await Contact(client);var community=await Json(await Send(client,"/api/v1/engagement/communities",HttpMethod.Post,new{kind="group",name="Member community",purpose="Member collaboration"}));var member=await Json(await Send(client,$"/api/v1/engagement/communities/{Id(community)}/members",HttpMethod.Post,new{contactId=Id(contact),role="member"}));var effect=Guid.NewGuid();var input=new Dictionary<string,string>{{"communityId",Id(community)},{"memberId",Id(member)}};await Invoke(app,client,"engagement.community.remove-member",input,effect);await Invoke(app,client,"engagement.community.remove-member",input,effect);Assert.Empty((await Json(await client.GetAsync($"/api/v1/engagement/communities/{Id(community)}")))["members"]!.AsArray());
 }
 [Fact] public async Task Event_cancellation_followup_includes_registrations_cancelled_by_the_domain_command()
 {
  using var app=new IdentityApiFactory();using var client=await Login(app);var session=(await client.GetFromJsonAsync<SessionResponse>("/api/v1/auth/session"))!;var contact=await Contact(client);var offering=await Json(await Send(client,"/api/v1/events/offerings",HttpMethod.Post,new{kind="event",name="Catalogue event",venue="Hall",startsAtUtc=DateTime.UtcNow.AddDays(3),endsAtUtc=DateTime.UtcNow.AddDays(4),capacity=10,passingScore=50}));await Json(await Send(client,$"/api/v1/events/offerings/{Id(offering)}/enrollments",HttpMethod.Post,new{contactId=Id(contact)}));var current=await Json(await client.GetAsync($"/api/v1/events/offerings/{Id(offering)}"));await Json(await Send(client,$"/api/v1/events/offerings/{Id(offering)}/cancel",HttpMethod.Post,new{version=Version(current["offering"]!),reason="Cancelled schedule"}));
  var graph=WorkflowOperationsTemplates.Build("event-reminders",session.UserId,new(EventChanges:true)).Graph with{Trigger="manual",Schedule=null};var draft=await Json(await Send(client,"/api/v1/workflows/definitions",HttpMethod.Post,new{name="Cancellation recipients",graph}));var published=await Json(await Send(client,$"/api/v1/workflows/definitions/{Id(draft)}/publish",HttpMethod.Post,new{version=Version(draft)}));await Json(await Send(client,$"/api/v1/workflows/definitions/{Id(draft)}/activate",HttpMethod.Post,new{version=Version(published["definition"]!)}));var run=await Json(await Send(client,$"/api/v1/workflows/definitions/{Id(draft)}/execute",HttpMethod.Post,new{recordId=Id(offering),requestKey=Guid.NewGuid().ToString()}),HttpStatusCode.Accepted);
  var worker=new WorkflowWorker(app.Services.GetRequiredService<IServiceScopeFactory>(),app.Services.GetRequiredService<WorkflowExecutionContext>(),NullLogger<WorkflowWorker>.Instance);for(var i=0;i<12;i++)await worker.TickAsync(default);var detail=await Json(await client.GetAsync("/api/v1/workflows/runs/"+Id(run)));Assert.Equal("completed",detail["run"]!["status"]!.GetValue<string>());var tasks=(await Json(await client.GetAsync("/api/v1/work/items"))).AsArray();Assert.Single(tasks);Assert.Equal(Id(contact),tasks[0]!["contactId"]!.GetValue<string>());
 }
 [Fact] public async Task Report_inspection_counts_actual_outstanding_invoices_without_business_mutation()
 {
  using var app=new IdentityApiFactory();using var client=await Login(app);var contact=await Contact(client);await Invoice(client,Id(contact));var report=await Invoke(app,client,"workflow.operations.inspect",new(){{"recordId",Id(contact)}});Assert.Equal("true",report.Outputs["hasExceptions"]);Assert.Contains("outstanding invoices: 1",report.Outputs["summary"]);Assert.Empty((await Json(await client.GetAsync("/api/v1/work/items"))).AsArray());
 }
}
